    public void refuseIfClosed(String sheetId, LocalDate date) {
        if (isClosed(sheetId, date)) {
            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period.");
        }
    }

    /**
     * Whether a claim due by this day lies inside a closed period. Holds the sheet first, so a
     * period cannot close while a change that relies on the answer is under way.
     */
    public boolean isClosed(String sheetId, LocalDate date) {
        sheetRows.findLockedById(sheetId);
        return periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date,
                date);
    }

    /** The period on the sheet a claim due by this day belongs to, if any. */
    public Optional<Period> on(String sheetId, LocalDate date) {
        return periods.findBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date, date);
    }

    /** Whether a claim due by this day lies inside a soft-closed period. */
    public boolean isSoftClosed(String sheetId, LocalDate date) {
        return periods.existsBySheetIdAndSoftClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId,
                date, date);
    }
}
package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/**
 * A period on a sheet: a name and a from and to date, both inclusive. A closed period keeps the
 * due-total it had when it was closed, and each person's due-total for it at that moment; so does a
 * soft-closed one, whose claims can still change.
 */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Soft-closed: the figures are fixed as for a closed period, but its claims can still change. */
    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    @Column(name = "closed_due")
    private BigDecimal closedDue;

    /** Each person's due-total fixed when the period was closed, by person id; empty while open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_due", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "due", nullable = false)
    private Map<Long, BigDecimal> closedDues = new HashMap<>();

    /** The last number given to a claim opened in this period under numbering per period. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** At most this many OPEN or PENDING claims per person may be in the period; null for no cap. */
    @Column(name = "claim_cap")
    private Integer claimCap;

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate, Integer claimCap) {
        this(sheetId, name, fromDate, toDate);
        this.claimCap = claimCap;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public Integer getClaimCap() {
        return claimCap;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoftClosed() {
        return softClosed;
    }

    public BigDecimal getClosedDue() {
        return closedDue;
    }

    public Map<Long, BigDecimal> getClosedDues() {
        return closedDues;
    }

    /** Give out the next claim number within this period. */
    public int nextClaimNumber() {
        return ++lastClaimNumber;
    }

    /**
     * Close the period, fixing each person's due-total for it at this moment; its own due-total is
     * their sum.
     */
    public void close(Map<Long, BigDecimal> dues) {
        fix(dues);
        this.closed = true;
        this.softClosed = false;
    }

    /**
     * Soft-close the period, fixing its figures as {@link #close} does while its claims can still
     * change.
     */
    public void softClose(Map<Long, BigDecimal> dues) {
        fix(dues);
        this.softClosed = true;
    }

    private void fix(Map<Long, BigDecimal> dues) {
        this.closedDues.clear();
        this.closedDues.putAll(dues);
        this.closedDue = dues.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Reopen the period: its due-total is live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedDue = null;
        this.closedDues.clear();
    }
}

